window.__posterData({"id": "matilda-helg", "name": "Matilda Helg", "folder": "Week44_AiPoster_MatildaHelg", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// COMMENTS \n// STEP 1: I asked for a refactor with no change in behavior. \n// STEP 2: I asked for pulsing, centered text with alternating colors in the drawsmalltexts() function. \n// STEP 3: I let the AI choose one feature for each page to change. I actually only asked for one at first, but the lasers left the rave page completely untouched, so I wanted both pages to get some attention and see what the AI could do. \n  // For the rave-page, I told it \"if you want to, you can add something of your choice for the other page too\". I wanted to leave the decision to the AI, since it had already done the first page. \n\n\n// The AI pulled all numbers out and named then constants. I didn't ask for this, but it made the code easier to read so I like it (Step 1)\nconst COLORS = ['#790D16', '#830000', '#BC0202', '#800020', '#6C1A1A', '#A4DD00'];\nconst LIME = '#A4DD00';\nconst FONT = 'ANTON';\n\nconst CANVAS_W = 600;\nconst CANVAS_H = 800;\nconst CIRCLE_COUNT = 40;\nconst CIRCLE_SIZE = 50;\nconst SCROLL_SPEED = 20;\n\n// I asked the AI to let the texts pulse between 10px and 100px (step 2)\nconst MIN_TEXT_SIZE = 10;\nconst MAX_TEXT_SIZE = 100;\nconst ORIGINAL_TEXT_SIZE = 30;\n\n// The AI picked lasers on it's own. I think the idea fits the theme, but I would not have thought about it myself. (Step 3)\n\nconst BEAM_COUNT = 5;\nconst BEAM_LENGTH = 1200;\nconst BEAM_FOLLOW = 0.08;   \n\n// It took a long time before I understood what theese meant. The AI  chose a tempo of the rave page without asking. \nconst BPM = 128;           \nconst BEAT_FLASH = 0.7;     \nconst BEAT_GROWTH = 0.8;   \nconst RING_MAX = 700;      \n\n// Instead of the three different text cells I had in the original, the AI but put each text in different arrays. I do think each array has its own speed and phase. I'm not sure I would have done it this way, but it did what I asked and when it's actually easy to understand (step 2)\n\nconst SMALL_TEXTS = [\n  { label: 'MATILDA HELG', x: 190, y: 50,  speed: 0.11, phase: 0,   colorEvery: 24 }, \n  { label: '18:00-03:00',  x: 50,  y: 430, speed: 0.07, phase: 2.1, colorEvery: 36 }, \n  { label: '18/11',        x: 500, y: 430, speed: 0.15, phase: 4.2, colorEvery: 30 }  \n];\n\nlet img;\nlet circles = [];    \nlet beams = [];       \nlet scrollX = 600;\n\nasync function setup() {\n  createCanvas(CANVAS_W, CANVAS_H);\n  img = await loadImage('raveposter.png');\n  frameRate(80);\n  textFont(FONT); // It did this is step 1, the font is set here now instead of in every function. \n\n  for (let i = 0; i < CIRCLE_COUNT; i++) {\n    circles.push({ x: random(width), y: random(height) });\n  }\n\n \n  initSmallTexts();\n  initBeams();\n}\n\nfunction draw() {\n // In  my original code, inbjudan () and kommer () were inside the draw(). The AI moved them out and renamed them. I didn't know that nested functions get defined once again in every frame, so I learned that here.    \n  if (mouseIsPressed) {\n    drawRave();\n  } else {\n    drawInvitation();\n  }\n}\n\n\n\nfunction drawInvitation() {\n  image(img, 0, 0, CANVAS_W, CANVAS_H); // The AI did this in step 1 to make the picture the same size as the canvas\n  filter(BLUR, 2);\n\n  drawBeams(); // The code is here because the beams are supposed to be on top of the texts\n  drawSmallTexts();\n  drawVibratingTitle();\n}\n\n// Step 3 - addition one \n// The AI added beams which is a feature I really enjoys. For starters, it lifts the playability since it's the mouse X&Y input that controls it. Also it contributes to the rave-feeling and the identity of my poster. The last thing i really liked, was that and made the invitation-page more fun to watch that the original and lifted the surprise element for the page. \n\n// If I would continue developing this poster, I think I would make the lasers brighter and make them move quicker. Overall, I really enjoyed this feature and I'm happy with the outcome. \n\nfunction initBeams() {\n  for (let i = 0; i < BEAM_COUNT; i++) {\n    beams.push({\n      ox: map(i, 0, BEAM_COUNT - 1, 40, CANVAS_W - 40),\n      oy: CANVAS_H,\n      angle: -HALF_PI, // Some things, like this line, I do not understand. After some research in p5.js, it says that HALF_PI is 90°, I just don't understand why the AI won't write 90°\n      speed: random(0.01, 0.03),\n      phase: random(TWO_PI)\n    });\n  }\n}\n\nfunction drawBeams() {\n  push();\n  strokeCap(ROUND);\n\n  // I understand this one clearly without any further instructions\n  const mouseOnCanvas = mouseX > 0 && mouseX < width && mouseY > 0 && mouseY < height;\n\n  beams.forEach((b, i) => {\n    // I had to ask the AI what this one did and apperently it's for when the lasers are functioning on their own \n    let target = -HALF_PI + sin(frameCount * b.speed + b.phase) * 0.7;\n\n// While thise one is for when you control them with your mouse \n    if (mouseOnCanvas) {\n      target = atan2(mouseY - b.oy, mouseX - b.ox);\n    } // no idea what atan2 means\n\n    b.angle = lerp(b.angle, target, BEAM_FOLLOW);\n\n    const ex = b.ox + cos(b.angle) * BEAM_LENGTH;\n    const ey = b.oy + sin(b.angle) * BEAM_LENGTH;\n\n    const c = color(COLORS[(floor(frameCount / 30) + i) % COLORS.length]);\n\n    const layers = [{ w: 18, a: 40 }, { w: 8, a: 90 }, { w: 3, a: 220 }];\n    for (const layer of layers) {\n      c.setAlpha(layer.a);\n      stroke(c);\n      strokeWeight(layer.w);\n      line(b.ox, b.oy, ex, ey);\n    }\n  });\n\n  pop();\n}\n\n// STEP 2 \n// Basically, I asked the AI to make the texts pulse individually and change colors. \n\n\nfunction initSmallTexts() {\n  push();\n  textSize(ORIGINAL_TEXT_SIZE);\n\n  \n  // The AI made the texts grow from its bottom left corner, so I asked for the starting point to be the center of the text. The AI solved it by the code below. \n  for (const t of SMALL_TEXTS) {\n    t.cx = t.x + textWidth(t.label) / 2;\n    t.cy = t.y - (textAscent() - textDescent()) / 2;\n    t.color = random(COLORS);\n  }\n// That is the part I understand the least, but it worked as i wanted. \n  pop();\n}\n\nfunction drawSmallTexts() {\n  push(); // The AI wrappes the texts in push and pop so the code doesn't leak into other texts. I knew that push and pop was for wrapping the text, but did not know that it suppresses other elements so that they don't leak into each other. \n  stroke(0);\n  textAlign(CENTER, CENTER);\n\n  for (const t of SMALL_TEXTS) {\n    const wave = sin(frameCount * t.speed + t.phase);\n    textSize(map(wave, -1, 1, MIN_TEXT_SIZE, MAX_TEXT_SIZE));\n\n// In the first version of the second step, the AI made the colors change every frame which was way to fast. I asked for it to be slower, the different intervals was the AIs idea and I like that they don't flicker in sync.  \n    \n    if (frameCount % t.colorEvery === 0) {\n      t.color = random(COLORS);\n    }\n\n    fill(t.color);\n    text(t.label, t.cx, t.cy);\n  }\n\n  pop();\n}\n\nfunction drawVibratingTitle() {\n  push();\n  rotate(sin(frameCount * 0.5) * 0.01);\n  fill(LIME);\n  textSize(70);\n  text('LÖRDAGSRAVE', 50, 500);\n  textSize(50);\n  text('INVITE ONLY', 150, 550);\n  pop();\n}\n\n// Step 3 \n// The beat gives the rave bage kind of a rhythm. The flash, circle size and rings now moves togheter. Before the page had a random flicker, now it feels like a planned random flicker. I think this change suits the rave night theme very well. \n// I gave the model free choice here and I'm mostly happy with it. I do think the original chaos was more \"me\" than the polished beat, but I guess thats because it's my knowledge limitation. \n\nfunction getBeat() {\n  const beatLength = 60000 / BPM;              \n  const phase = (millis() % beatLength) / beatLength; \n  return {\n    phase: phase,\n    pulse: pow(1 - phase, 3),                 \n    index: floor(millis() / beatLength)        \n  };\n}\n\nfunction drawRave() {\n  const beat = getBeat();\n\n\n  background(lerpColor(color('black'), color(COLORS[4]), beat.pulse * BEAT_FLASH));\n\n  drawVibratingHeadline();\n  drawCircles(beat.pulse);\n  drawBeatRing(beat);\n  drawScrollingText();\n}\n\nfunction drawVibratingHeadline() {\n  push();\n  rotate(sin(frameCount * 0.5) * 0.03);\n  strokeWeight(0);\n  textSize(250);\n  fill(random(COLORS));\n  text('RAVE', 10, 250);\n  text('NIGHT', 10, 450);\n  pop();\n}\n\n// This function is similar to my original, and I understand it compleatly\nfunction drawCircles(pulse) {\n  const movingIndex = floor(random(CIRCLE_COUNT));\n  const size = CIRCLE_SIZE * (1 + pulse * BEAT_GROWTH); \n\n  circles.forEach((c, i) => {\n    fill(random(COLORS));\n\n    if (i === movingIndex) {\n      c.x = random(width);\n      c.y = random(height);\n    }\n    circle(c.x, c.y, size);\n  });\n}\n\nfunction drawBeatRing(beat) {\n  push();\n  noFill();\n\n  const c = color(COLORS[beat.index % COLORS.length]);\n  c.setAlpha(255 * (1 - beat.phase));\n  stroke(c);\n  strokeWeight(6);\n  circle(mouseX, mouseY, beat.phase * RING_MAX);\n\n  pop();\n  // There are some specific words that I don't understand, but overall it's easy to track and understand what the code does \n}\n\n// This is the same as the original \nfunction drawScrollingText() {\n  push();\n  strokeWeight(0);\n  textSize(90);\n  fill('white');\n  text('RAVE', scrollX, 500);\n  text('NIGHT', scrollX, 580);\n  pop();\n\n  scrollX += SCROLL_SPEED;\n  if (scrollX > width + 600) {\n    scrollX = -600;\n  }\n}", "assets": {"raveposter.png": {"mime": "image/webp", "b64": ""}}});
